var i=`webhooks-and-message-queues`;var s=69;var o={en:[{id:`T069-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Which description best captures the main purpose of `},{t:`Webhooks & Message Queues`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Backward compatibility lets newer systems continue serving existing clients and stored data.`},{id:`B`,text:`Rate limiting constrains request frequency or cost; throttling delays or rejects traffic to protect capacity and fairness.`},{id:`C`,text:`Remote Procedure Call presents network operations as service methods; gRPC commonly uses Protocol Buffers, HTTP/2 and generated contracts.`},{id:`D`,text:`Webhooks deliver events via outbound HTTP calls; message queues broker asynchronous delivery between producers and consumers.`}]},{id:`T069-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Which implementation approach most directly applies `},{t:`Webhooks & Message Queues`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Design schema types and resolvers around domain capabilities, use DataLoader or batching to avoid N+1 fetches, and constrain depth, complexity and pagination.`},{id:`B`,text:`Model resource identity with URIs, use HTTP methods according to semantics, return appropriate status codes, support caching when correct, and expose links when hypermedia is part of the contract.`},{id:`C`,text:`Define service methods and schema evolution rules, propagate deadlines and cancellation, authenticate each call and understand streaming modes.`},{id:`D`,text:`Design retries, deduplication, signatures, replay protection, dead-letter handling and schema evolution.`}]},{id:`T069-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`A team faces this situation: `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0},{t:` What is the most appropriate response?`}]}],options:[{id:`A`,text:`A reservation API may expose POST /reservations for creation, GET for reads, PATCH for partial changes, and a dedicated cancellation action when cancellation is a meaningful state transition.`},{id:`B`,text:`A public search API allows small bursts but caps sustained requests; a login endpoint additionally limits attempts per account and network source while detecting abuse.`},{id:`C`,text:`Field-level checks must still prevent exposing private billing details to unauthorized staff.`},{id:`D`,text:`The receiver verifies authenticity, stores the event ID, acknowledges quickly and processes the state change asynchronously once.`}]},{id:`T069-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`When using `},{t:`Webhooks & Message Queues`,b:!0},{t:`, which trade-off or common mistake deserves particular attention?`}]}],options:[{id:`A`,text:`Browser support, proxies, debugging and load balancing require special consideration.`},{id:`B`,text:`Webhook endpoints are exposed to forged requests, slow handlers and SSRF-like delivery misconfiguration.`},{id:`C`,text:`Client-side route guards improve UX but are not security controls.`},{id:`D`,text:`Versioning cannot compensate for undocumented behavior.`}]},{id:`T069-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Is the following statement accurate?`}]},{k:`quote`,runs:[{t:`Both decouple work in time but have different trust and operational models.`}]}]},{id:`T069-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`True or false?`}]},{k:`quote`,runs:[{t:`A webhook delivery guarantees the consumer processes the event exactly once.`}]}]},{id:`T069-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Is this guidance or caution accurate for the concept?`}]},{k:`quote`,runs:[{t:`Queue consumers can poison the queue without retry limits and dead-letter visibility.`}]}]},{id:`T069-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` statements that correctly characterize `},{t:`Webhooks & Message Queues`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`A single global request limit is always sufficient for every API endpoint.`},{id:`B`,text:`A webhook receiver may skip signature verification when it uses HTTPS.`},{id:`C`,text:`Webhooks deliver events via outbound HTTP calls; message queues broker asynchronous delivery between producers and consumers.`},{id:`D`,text:`Design retries, deduplication, signatures, replay protection, dead-letter handling and schema evolution.`}]},{id:`T069-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Select `},{t:`exactly two`,b:!0},{t:` observations consistent with a sound application of `},{t:`Webhooks & Message Queues`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`The receiver verifies authenticity, stores the event ID, acknowledges quickly and processes the state change asynchronously once.`},{id:`B`,text:`A webhook delivery guarantees the consumer processes the event exactly once.`},{id:`C`,text:`RPC calls make partial network failures behave like local function errors.`},{id:`D`,text:`Queue consumers can poison the queue without retry limits and dead-letter visibility.`}]},{id:`T069-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`An AI agent works on this task: `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0},{t:` Which proposed verification task most directly tests the required behavior?`}]}],options:[{id:`A`,text:`Ask an agent to design tenant-aware authorization for bookings, including service accounts and revoked permissions. Require tests for horizontal and vertical privilege escalation.`},{id:`B`,text:`Have an agent specify a gRPC inventory API, with deadline propagation, backward-compatible field changes and tests for unavailable peers.`},{id:`C`,text:`Ask an agent to classify a list of schema changes as additive or breaking and produce a rollout plan with compatibility tests for old mobile clients.`},{id:`D`,text:`Ask an agent to design signed inbound webhooks and an internal queue with deduplication, quick acknowledgment, retries and replay-safe processing.`}]},{id:`T069-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`How will you recover a message that was received successfully but failed business processing?`}]}]},{id:`T069-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`In this situation — `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0},{t:` — what two specific signals would make you change the design used for `},{t:`Webhooks & Message Queues`,b:!0},{t:`? Explain how you would measure them.`}]}]},{id:`T069-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`For this case — `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0},{t:` — propose three checks for `},{t:`Webhooks & Message Queues`,b:!0},{t:`: one normal case, one failure or boundary case, and one check for changing requirements. Give expected outcomes.`}]}]},{id:`T069-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Design decision: `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0}]},{k:`p`,runs:[{t:`Describe your chosen approach, an alternative you rejected, the most important trade-off, and two concrete acceptance checks. Keep the proposal feasible for a real project.`}]}]},{id:`T069-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Review an AI-generated change for `},{t:`Webhooks & Message Queues`,b:!0},{t:`. The agent says the feature is complete for this situation: `},{t:`A payment provider sends a signed charge-success webhook.`,b:!0},{t:`. It shows a successful demo, but its PR contains no explicit failure-case analysis or verification plan.`}]},{k:`p`,runs:[{t:`Identify at least `},{t:`two topic-specific risks`,b:!0},{t:`, propose the tests/evidence required before approval, and state whether you would approve, request changes, or block deployment. Explain why.`}]}]}],ua:[{id:`T069-Q01`,type:`single_choice`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Яке формулювання найточніше передає призначення `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Зворотна сумісність дозволяє новій системі підтримувати старих клієнтів і дані.`},{id:`B`,text:`Rate limiting обмежує частоту або вартість запитів; throttling затримує чи відхиляє трафік, щоб захистити ресурси та справедливість.`},{id:`C`,text:`RPC представляє мережеві операції як методи сервісу; gRPC часто використовує Protocol Buffers, HTTP/2 і згенеровані контракти.`},{id:`D`,text:`Webhook передає події вихідним HTTP-запитом; черга повідомлень доставляє асинхронні задачі між виробником і споживачем.`}]},{id:`T069-Q02`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Який спосіб реалізації найкраще відповідає `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Проєктуйте типи й resolvers навколо доменних можливостей, використовуйте batching для запобігання N+1 та обмежуйте глибину, складність і пагінацію.`},{id:`B`,text:`Моделюйте ідентичність ресурсу через URI, дотримуйтеся семантики HTTP-методів, повертайте належні статуси, застосовуйте кешування, а посилання між ресурсами — коли це частина контракту.`},{id:`C`,text:`Визначайте методи сервісу й правила еволюції схем, передавайте deadline та cancellation, автентифікуйте виклики й розумійте streaming.`},{id:`D`,text:`Проєктуйте повтори, дедуплікацію, підписи, захист від replay, dead-letter та еволюцію схем.`}]},{id:`T069-Q03`,type:`single_choice`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Команда має таку ситуацію: `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0},{t:` Яке рішення найдоречніше?`}]}],options:[{id:`A`,text:`API бронювань може надавати POST /reservations для створення, GET для читання, PATCH для часткових змін та окрему дію скасування, коли вона є повноцінним переходом стану.`},{id:`B`,text:`Публічний пошук дозволяє короткі піки, але обмежує тривале навантаження; login також лімітує спроби за акаунтом і джерелом та виявляє зловживання.`},{id:`C`,text:`Перевірки на рівні полів повинні не допустити витоку приватних платіжних даних.`},{id:`D`,text:`Приймач перевіряє автентичність, зберігає ID, швидко підтверджує прийом і асинхронно обробляє зміну стану.`}]},{id:`T069-Q04`,type:`single_choice`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Який компроміс або типову помилку особливо важливо врахувати під час застосування `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`?`}]}],options:[{id:`A`,text:`Підтримка браузера, proxy, дебаг і балансування потребують уваги.`},{id:`B`,text:`Webhook endpoints ризикують підробленими запитами, повільною обробкою й помилками налаштування адрес доставки.`},{id:`C`,text:`Клієнтські route guards покращують UX, але не є захистом.`},{id:`D`,text:`Версіонування не виправляє недокументованої поведінки.`}]},{id:`T069-Q05`,type:`true_false`,difficulty:`foundation`,points:1,prompt:[{k:`p`,runs:[{t:`Чи правильне твердження?`}]},{k:`quote`,runs:[{t:`Обидва розділяють роботу в часі, але мають різні моделі довіри та експлуатації.`}]}]},{id:`T069-Q06`,type:`true_false`,difficulty:`applied`,points:1,prompt:[{k:`p`,runs:[{t:`Правда чи неправда?`}]},{k:`quote`,runs:[{t:`Доставка вебхука гарантує одноразову обробку події споживачем.`}]}]},{id:`T069-Q07`,type:`true_false`,difficulty:`advanced`,points:1,prompt:[{k:`p`,runs:[{t:`Чи коректна ця порада або пересторога для цієї концепції?`}]},{k:`quote`,runs:[{t:`Споживачі черги можуть зациклити отруйне повідомлення без ліміту повторів.`}]}]},{id:`T069-Q08`,type:`multiple_select`,difficulty:`applied`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` твердження, які правильно характеризують `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Одного глобального ліміту запитів завжди достатньо для всіх endpoint API.`},{id:`B`,text:`Одержувач вебхука може пропустити перевірку підпису, якщо є HTTPS.`},{id:`C`,text:`Webhook передає події вихідним HTTP-запитом; черга повідомлень доставляє асинхронні задачі між виробником і споживачем.`},{id:`D`,text:`Проєктуйте повтори, дедуплікацію, підписи, захист від replay, dead-letter та еволюцію схем.`}]},{id:`T069-Q09`,type:`multiple_select`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`Оберіть `},{t:`рівно два`,b:!0},{t:` спостереження, що відповідають правильному застосуванню `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`.`}]}],options:[{id:`A`,text:`Приймач перевіряє автентичність, зберігає ID, швидко підтверджує прийом і асинхронно обробляє зміну стану.`},{id:`B`,text:`Доставка вебхука гарантує одноразову обробку події споживачем.`},{id:`C`,text:`RPC-виклики перетворюють часткові мережеві збої на звичайні локальні помилки функцій.`},{id:`D`,text:`Споживачі черги можуть зациклити отруйне повідомлення без ліміту повторів.`}]},{id:`T069-Q10`,type:`scenario_choice`,difficulty:`advanced`,points:2,prompt:[{k:`p`,runs:[{t:`ШІ-агент працює над завданням: `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0},{t:` Яка запропонована перевірка найкраще підтверджує потрібну поведінку?`}]}],options:[{id:`A`,text:`Попросіть агента спроєктувати tenant-aware авторизацію бронювань, включно із сервісними акаунтами та відкликаними правами. Вимагайте тести горизонтального й вертикального підвищення привілеїв.`},{id:`B`,text:`Попросіть агента описати gRPC API складу з передаванням deadline, сумісними змінами полів і тестами недоступного сервісу.`},{id:`C`,text:`Попросіть агента розділити зміни схеми на сумісні й несумісні та створити план релізу з тестами старих мобільних клієнтів.`},{id:`D`,text:`Попросіть агента спроєктувати підписані вхідні webhook і внутрішню чергу з дедуплікацією, швидким ACK, повторами й захистом від replay.`}]},{id:`T069-Q11`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Як відновити повідомлення, яке успішно прийнято, але не вдалося обробити бізнес-логікою?`}]}]},{id:`T069-Q12`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`У ситуації `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0},{t:` назвіть два конкретні сигнали, за яких ви змінили б рішення для `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`. Як саме їх виміряти?`}]}]},{id:`T069-Q13`,type:`short_answer`,difficulty:`advanced`,points:4,prompt:[{k:`p`,runs:[{t:`Для випадку `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0},{t:` запропонуйте три перевірки `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`: типовий сценарій, збій або граничну умову та зміну вимог. Наведіть очікувані результати.`}]}]},{id:`T069-Q14`,type:`design_decision`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Архітектурне рішення: `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0}]},{k:`p`,runs:[{t:`Опишіть обраний підхід, відхилену альтернативу, найважливіший компроміс і дві конкретні перевірки приймання. Рішення має бути практичним.`}]}]},{id:`T069-Q15`,type:`ai_code_review`,difficulty:`expert`,points:6,prompt:[{k:`p`,runs:[{t:`Перевірте зміну, згенеровану ШІ, з теми `},{t:`Вебхуки та черги повідомлень`,b:!0},{t:`. Агент стверджує, що функція готова для ситуації: `},{t:`Платіжний провайдер надсилає підписаний webhook про оплату.`,b:!0},{t:`. Він показав успішне демо, але PR не містить аналізу збоїв або плану перевірок.`}]},{k:`p`,runs:[{t:`Назвіть щонайменше `},{t:`два ризики, специфічні для теми`,b:!0},{t:`, запропонуйте тести/докази перед погодженням і оберіть: погодити, повернути на доопрацювання чи заблокувати реліз. Обґрунтуйте рішення.`}]}]}]};var n={slug:i,topicId:69,questions:o};export{n as default,o as questions,i as slug,s as topicId};